using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FixReverseCorrectionDecorativeContacts {
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");int removed=0;foreach(string scene in new[]{"DansBackyardReverse","DansBackyardForward"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");var root=GameObject.Find("Reverse optional forest shortcuts");foreach(var c in root.GetComponentsInChildren<Collider>().Where(c=>c.name=="Grass intrusion"||c.name=="Broken logging wheel paths").ToArray()){UnityEngine.Object.DestroyImmediate(c);removed++;}EditorSceneManager.MarkSceneDirty(root.scene);EditorSceneManager.SaveScene(root.scene);}EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");File.WriteAllText("Docs/ReverseCorrection/decorative-contacts.txt","Removed "+removed+" duplicate decorative grass/wheel-path colliders. Solid Ground_ ridge meshes retain collision and existing normal correction.");return "Removed decorative colliders: "+removed;}
}
